import{_ as e,c as a,o as s,a2 as i}from"./chunks/framework.DdOM6S6U.js";const v=JSON.parse('{"title":"Coverage Commands","description":"","frontmatter":{"sidebarPos":6,"sidebarTitle":"Overview","sidebarGroupTitle":"Coverage"},"headers":[],"relativePath":"guide/console/coverage/overview.md","filePath":"guide/console/coverage/overview.md","lastUpdated":1778363927000}'),t={name:"guide/console/coverage/overview.md"},r=i(`<h1 id="coverage-commands" tabindex="-1">Coverage Commands <a class="header-anchor" href="#coverage-commands" aria-label="Permalink to &quot;Coverage Commands&quot;">​</a></h1><p>The Coverage command group wraps the <code>CoverageService</code> / <code>Coverage</code> facade to analyse Clover XML reports, generate reports, check PR thresholds, watch live coverage changes, and AI-generate missing tests.</p><table><thead><tr><th>Command</th><th>Description</th></tr></thead><tbody><tr><td><a href="/guide/console/coverage/coverage-analyze">coverage:analyze</a></td><td>Analyse a Clover XML report and display per-file coverage</td></tr><tr><td><a href="/guide/console/coverage/coverage-pr-check">coverage:pr:check</a></td><td>Compare coverage against a base branch and fail if below threshold</td></tr><tr><td><a href="/guide/console/coverage/coverage-report">coverage:report</a></td><td>Generate JSON, Markdown, or HTML coverage reports</td></tr><tr><td><a href="/guide/console/coverage/coverage-generate-tests">coverage:generate-tests</a></td><td>Scaffold missing tests — optionally via AI provider</td></tr><tr><td><a href="/guide/console/coverage/coverage-watch">coverage:watch</a></td><td>Poll a Clover file and display diffs as coverage changes</td></tr></tbody></table><h2 id="prerequisites" tabindex="-1">Prerequisites <a class="header-anchor" href="#prerequisites" aria-label="Permalink to &quot;Prerequisites&quot;">​</a></h2><p>All commands require a Clover XML file produced by PHPUnit or Pest:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --coverage-clover=storage/app/clover.xml</span></span></code></pre></div><p>The default file name and directory can be overridden per command with <code>--cloverName</code> and <code>--cloverDir</code>.</p><h2 id="common-workflows" tabindex="-1">Common Workflows <a class="header-anchor" href="#common-workflows" aria-label="Permalink to &quot;Common Workflows&quot;">​</a></h2><h3 id="generate-a-local-coverage-report" tabindex="-1">Generate a local coverage report <a class="header-anchor" href="#generate-a-local-coverage-report" aria-label="Permalink to &quot;Generate a local coverage report&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --coverage-clover=storage/app/clover.xml</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:coverage:analyze</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">        # quick per-file summary</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:coverage:report</span><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">         # JSON / markdown / HTML rendering</span></span></code></pre></div><h3 id="gate-a-pull-request-on-coverage" tabindex="-1">Gate a pull request on coverage <a class="header-anchor" href="#gate-a-pull-request-on-coverage" aria-label="Permalink to &quot;Gate a pull request on coverage&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:coverage:pr:check</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --threshold=80</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --base=main</span></span></code></pre></div><p>Fails with a non-zero exit code when PR coverage drops below the threshold — wire it into CI.</p><h3 id="scaffold-missing-tests-optionally-ai-assisted" tabindex="-1">Scaffold missing tests (optionally AI-assisted) <a class="header-anchor" href="#scaffold-missing-tests-optionally-ai-assisted" aria-label="Permalink to &quot;Scaffold missing tests (optionally AI-assisted)&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:coverage:generate-tests</span></span></code></pre></div><p>Creates PHPUnit/Pest test stubs for uncovered methods. When an AI provider is configured, <code>--ai</code> fills in assertions; otherwise the stubs are empty scaffolds.</p><h3 id="watch-coverage-during-tdd" tabindex="-1">Watch coverage during TDD <a class="header-anchor" href="#watch-coverage-during-tdd" aria-label="Permalink to &quot;Watch coverage during TDD&quot;">​</a></h3><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> modularous:coverage:watch</span></span></code></pre></div><p>Polls the Clover file and prints a diff whenever coverage changes — run alongside your test runner for fast feedback.</p><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="/system-reference/backend/services/overview">CoverageService</a> — underlying service</li><li><a href="/system-reference/backend/facades/overview">Coverage facade</a> — programmatic access</li></ul>`,21),o=[r];function n(l,d,h,c,p,g){return s(),a("div",null,o)}const u=e(t,[["render",n]]);export{v as __pageData,u as default};
